import { test, expect } from '@playwright/test';

test.describe('File Upload Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload'); // Replace with the actual URL of the upload page
  });

  test('should display an error message for unsupported file type', async ({ page }) => {
    const filePath = 'path/to/unsupported-file.txt'; // Replace with an actual unsupported file path
    await page.setInputFiles(getByLabel('File Upload'), filePath);
    await page.click(getByRole('button', { name: /upload/i }));

    const errorMessage = await page.getByText(/unsupported file type/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should not display error message for supported file type', async ({ page }) => {
    const filePath = 'path/to/supported-file.jpg'; // Replace with an actual supported file path
    await page.setInputFiles(getByLabel('File Upload'), filePath);
    await page.click(getByRole('button', { name: /upload/i }));

    const errorMessage = page.getByText(/unsupported file type/i);
    await expect(errorMessage).not.toBeVisible();
  });
});
